ANNOTATIONS = [
    (1, 'before', '''Diff 查看器左侧的文件清单。三件事：把文件数**限制在 5 行**并做滚动窗口（含「上方还有 N 个 / 下方还有 N 个」提示）、路径**从头部截断**（保留尾部文件名）、以及每种不可 diff 的文件（未跟踪 / 二进制 / 超长）各给一句状态而不是空白。'''),
    (9, 'before', '''`MAX_VISIBLE_FILES = 5` 是个硬上限而不是可配的。原因是这个清单挤在 diff 正文旁边，它的高度直接吃掉正文的行数——文件一多就该让用户用滚动而不是把清单撑长。'''),
    (14, 'before', '''注意这里 `useTerminalSize` 与滚动窗口计算都放在**两个提前 return 之前**：React 的 hook 顺序必须稳定，若把 useMemo 放到 `files.length === 0` 的 return 之后，文件数从 0 变 1 时 hook 数量就变了。注释里也写了「必须在 early return 之前，为了 hook 规则」。'''),
    (25, 'before', '''两条件合并成一个判断：文件数 ≤ 5 时窗口就是全量。这时 `startIndex` 恒为 0，下面所有「上方还有更多」的判断都会自然为假，不需要额外分支。'''),
    (40, 'before', '''常规窗口算法：让选中项**居中**（`selectedIndex - floor(5/2)`），再钳到 0。居中而不是贴边，是因为用户用上下键逐项浏览时，希望看到「前后各两个」的上下文。'''),
    (42, 'before', '''窗口右端越界时，不是把 end 钳到 length 就完事，还要**回拉 start**（`start = end - 5`）。只钳 end 会让最后几项时窗口变短、清单高度从 5 行掉到 2 行，整块布局跟着跳。'''),
    (64, 'before', '''空列表单独早退，返回一行 dim 的 No changed files。它没有像 FuzzyPicker 那样预留等高占位——因为 diff 查看器本身就是整屏布局，少 5 行不会导致输入框跳动，与 picker 的场景不同。'''),
    (85, 'before', '''路径可用宽度是 `columns - 16 - 3 - 4`：16 预留右侧的增删行数，3 是边框与间距，4 是安全余量。和 MarkdownTable 里的 SAFETY_MARGIN 是同一个思路——终端布局里必须手算并留余量，否则窄终端下会挤出容器。'''),
    (89, 'before', '''上方提示只在**需要分页**时才渲染，且没有更多时渲染一个空格（不是 null）。渲染空格是为了保持清单总高度恒定：有提示与无提示差一行，会让下面的文件项整体上移一格、光标所指的文件看起来变了。'''),
    (129, 'before', '''下方提示与上方对称，数量用 `files.length - endIndex`。`plural(n, file)` 处理单复数，避免出现 `1 more files`。'''),
    (161, 'before', '''路径用 `truncateStartToWidth` **从头部截断**，保留尾巴。这是路径展示的通用选择：文件名与最后两级目录才是辨别依据，`/Users/xxx/projects/...` 这段前缀对所有人几乎一样。反过来从尾部截断（`truncateToWidth`）会正好砍掉最有信息量的部分。'''),
    (169, 'before', '''指针用 `figures.pointer + 空格`，未选中时用**两个空格**而不是空串——保证选中前后每行的字符数完全一致。差一个字符会让整份清单在按上下键时左右抖动。'''),
    (174, 'before', '''选中态同时用了 `bold`、`color=「background」`、`inverse` 三种强调。`inverse` 是反色（前景背景互换），在终端里这是最稳的「整行高亮」手段；加 bold 是为了在部分终端反色不够明显时仍有区分。'''),
    (184, 'before', '''路径文本与右侧统计之间插一个 `flexGrow={1}` 的空盒，把两者顶到两端。这是 Ink 里实现「左对齐 + 右对齐」的标准写法——没有 justify-content，只能靠弹性占位。'''),
    (215, 'before', '''未跟踪文件走单独分支：只显示 untracked，不显示增删行数。因为未跟踪文件没有基线可比，git 算不出增删；显示 +0 -0 反而误导用户以为是空文件。'''),
    (219, 'before', '''三种「不可 diff」状态的 dimColor 都取 `!isSelected`：未选中时变暗、选中时保持正常亮度。原因是选中行已经反色显示，再叠加 dim 会几乎看不清——这是「强调叠加要互斥」的一个具体例子。'''),
    (260, 'before', '''增删数量之间那个空格只在**两者都大于 0** 时才插（`&& ' '`）。若只有增或只有减，中间那句是空字符串直接消失，不会留下一个孤零零的空格。这种「条件分隔符」在拼行内文本时很常见，比先拼再 trim 更干净。'''),
    (272, 'before', '''`(truncated)` 又是一个独立的小尾巴，说明这个文件的 diff 被截断过（大文件保护）。它是清单里唯一提示「你看到的不是全部」的地方——点进去看到的 diff 也是截断的，所以这个标记必须在列表层就出现。'''),
]
